@spec tv_freeze_group_spec  src=tests/specs/tv_freeze_group_spec.lua  loc=176  cases=4
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), groupManager (h.gm)
@surface   ds:assign, tm:rebuild, tm:addEvent, tm:flush, fm:dump, vm:setGridSize, ec:setPos, cmgr:invoke, ds:get, gm:eachInstance, gm:stateOf, tm:getChannel, tm:subscribe, gm:markGroup, tm:freezeRect, vm:freezeMode
@harness   mk

# Intent
  Track B (fx freeze): the tv verb that converts a producer and mints a stock group over its
  own output. tm_fx_region_spec pins the conversion and the thin; this spec is the wiring --
  the gate, the mint, and the one undo block they share.
  see design/fx-freeze.md § Freeze to group

# Helpers
  @fn injectMixed(h, over)  @ 13-19
      -- A mixed chain over a note: the arp promotes derived notes, the sine leaves pb breakpoints,
      -- so the one fixture yields both member kinds without registering a stub generator.
  @fn addNote(h)  @ 21-25
  @fn fxColFor(h, chan)  @ 27-31
  @fn noteColIdx(h, chan)  @ 33-37
  @fn authoredUuid(h)  @ 39-41
  @fn authoredPitches(h)  @ 43-50
  @fn blockCounter(h)  @ 54-62
      -- util.atomic reads reaper.Undo_BeginBlock at call time, so a stub installed after the wrap still
      -- counts. Outermost blocks only: inner blocks collapse into the verb's.

# Cases
  @case 'freeze to group: the conversion mints one group over its own output'  [harness]  @ 67-104
  @case 'freeze to group: two rebuilds, one undo block'  [harness]  @ 111-130
  @case 'freeze to group: a colliding footprint declines before anything moves'  [harness]  @ 137-156
  @case 'freeze to group: a plain note at the caret is no producer'  [harness]  @ 160-174

